/// Output flags parsed once by the CLI host before command dispatch.
///
/// These are only caller-provided choices. Terminal and environment facts are
/// collected by the host and resolved by `OutputProfile`.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct OutputFlags {
    pub json: bool,
    pub quiet: bool,
    pub verbose: bool,
    pub color: ColorRequest,
}

impl OutputFlags {
    /// Parse output policy flags from the command-owned argv prefix.
    pub fn parse(args: &[String]) -> Result<Self, OutputProfileError> {
        let mut color = ColorRequest::Auto;
        for argument in args {
            if let Some(value) = argument.strip_prefix("--color=") {
                color = ColorRequest::parse(value)?;
            } else if argument == "--color" {
                // Preserve the existing CLI spelling: a bare --color enables
                // styling, while --color=<mode> selects an explicit mode.
                color = ColorRequest::Always;
            }
        }
        Ok(Self {
            json: machine_output_requested(args),
            quiet: args.iter().any(|argument| argument == "--quiet"),
            verbose: args
                .iter()
                .any(|argument| argument == "--verbose" || argument == "-v"),
            color,
        })
    }
}

/// One reserved word or sigil, for `jet inspect reserved` (#1659 criterion 5).
pub struct ReservedEntry {
    pub spelling: &'static str,
    pub kind: &'static str,
    pub note: &'static str,
}

/// D-MEM1 / D-SHAPE-COPY1=A / D-CONST-RETIRE1: the five teaching-reserved
/// words — real identifiers a user cannot bind because the lexer/parser
/// recognizes them only to redirect to their current spelling. Never in
/// `crate::Syntax::JET_KEYWORD_LIST`.
pub const TEACHING_RESERVED: &[ReservedEntry] = &[
    ReservedEntry { spelling: crate::Syntax::KW_COPY, kind: "teaching-reserved word", note: "retired; write `~value` instead (E0991)" },
    ReservedEntry { spelling: crate::Syntax::KW_MUTATE, kind: "teaching-reserved word", note: "retired; write `&value` instead (E0056)" },
    ReservedEntry { spelling: crate::Syntax::KW_MOVE, kind: "teaching-reserved word", note: "retired as a bare prefix; write `^value` instead (E0057); `.take(n)` stays a valid method" },
    ReservedEntry { spelling: crate::Syntax::KW_CONST, kind: "teaching-reserved word", note: "retired; write `@name` instead (E0374)" },
    ReservedEntry { spelling: crate::Syntax::FOREIGN_UNSAFE, kind: "teaching-reserved word", note: "the foreign spelling; write `#Unsafe(\"reason\") { … }` instead (E0031/E0003)" },
];

/// Sigils with compiler meaning outside ordinary operators.
pub const RESERVED_SIGILS: &[ReservedEntry] = &[
    ReservedEntry {
        spelling: crate::Syntax::SIGIL_BIND_IMMUT,
        kind: "sigil",
        note: "bind an immutable local",
    },
    ReservedEntry {
        spelling: crate::Syntax::SIGIL_BIND_MUT,
        kind: "sigil",
        note: "bind a mutable local",
    },
    ReservedEntry {
        spelling: crate::Syntax::SIGIL_WRITE,
        kind: "sigil",
        note: "borrow for write (D-MEM1)",
    },
    ReservedEntry {
        spelling: crate::Syntax::SIGIL_MOVE,
        kind: "sigil",
        note: "take/move ownership (D-MEM1)",
    },
    ReservedEntry {
        spelling: crate::Syntax::SIGIL_COPY,
        kind: "sigil",
        note: "produce an owned copy (D-SHAPE-COPY1)",
    },
    ReservedEntry {
        spelling: crate::Syntax::COMPTIME_MARK,
        kind: "sigil",
        note: "compile-time value or block (S57)",
    },
    ReservedEntry {
        spelling: crate::Syntax::SIGIL_FENCE_OPEN,
        kind: "sigil",
        note: "open a comptime fence",
    },
    ReservedEntry {
        spelling: crate::Syntax::SIGIL_FENCE_CLOSE,
        kind: "sigil",
        note: "close a comptime fence",
    },
    ReservedEntry {
        spelling: crate::Syntax::SIGIL_SPREAD,
        kind: "sigil",
        note: "spread elements",
    },
];

/// Plain-text render of `jet inspect reserved`.
pub fn reserved_report_text() -> String {
    let mut out = String::from("keywords:\n");
    for word in crate::Syntax::JET_KEYWORD_LIST {
        out.push_str(&format!("  {word}\n"));
    }
    out.push_str("\nteaching-reserved words (not valid identifiers):\n");
    for entry in TEACHING_RESERVED {
        out.push_str(&format!("  {:<10} {}\n", entry.spelling, entry.note));
    }
    out.push_str("\nsigils:\n");
    for entry in RESERVED_SIGILS {
        out.push_str(&format!("  {:<10} {}\n", entry.spelling, entry.note));
    }
    out
}

/// `--json` render of `jet inspect reserved`.
pub fn reserved_report_json() -> String {
    fn esc(s: &str) -> String {
        s.chars()
            .flat_map(|c| match c {
                '"' => "\\\"".chars().collect::<Vec<_>>(),
                '\\' => "\\\\".chars().collect(),
                c => vec![c],
            })
            .collect()
    }
    let keywords = crate::Syntax::JET_KEYWORD_LIST
        .iter()
        .map(|word| format!("\"{}\"", esc(word)))
        .collect::<Vec<_>>()
        .join(",");
    let render_entries = |entries: &[ReservedEntry]| {
        entries
            .iter()
            .map(|entry| {
                format!(
                    "{{\"spelling\":\"{}\",\"kind\":\"{}\",\"note\":\"{}\"}}",
                    esc(entry.spelling),
                    esc(entry.kind),
                    esc(entry.note)
                )
            })
            .collect::<Vec<_>>()
            .join(",")
    };
    let payload = format!(
        "{{\"keywords\":[{}],\"teaching_reserved\":[{}],\"sigils\":[{}]}}",
        keywords,
        render_entries(TEACHING_RESERVED),
        render_entries(RESERVED_SIGILS),
    );
    StatusEnvelope::new("inspect.reserved", true)
        .with_field(
            "reserved",
            StatusValue::parse(&payload).expect("reserved report payload must be valid JSON"),
        )
        .json()
}

/// One global flag that applies across commands.
pub const DRY_RUN_FLAG: &str = "--dry-run";
/// The one spelling that selects machine-readable command output.
pub const MACHINE_OUTPUT_FLAG: &str = "--json";
pub const CANVAS_FLAG: &str = "--canvas";

pub fn machine_output_requested(args: &[String]) -> bool {
    args.iter().any(|arg| arg == MACHINE_OUTPUT_FLAG)
        || args.first().is_some_and(|arg| arg == "compiler")
        || args
            .windows(2)
            .any(|pair| pair[0] == "inspect" && pair[1] == "compiler")
}

#[derive(Clone)]
pub struct FlagSpec {
    /// Long form, e.g. `--json` (always present).
    pub long: &'static str,
    /// One-line help, used in completions and the man page.
    pub help: &'static str,
}

/// One subcommand of `jet` — a bare leaf (`build`, `run`, …) or a namespaced
/// group (`registry`, …) that owns nested actions. #1659 criterion 1
/// (round 2): this is the ONE declaration dispatch, help, man, and completions
/// all render from — a group is a row here with non-empty `actions`, not a
/// second parallel table.
pub struct CommandSpec {
    pub name: &'static str,
    /// One-line summary (man + completion description).
    pub summary: &'static str,
    /// Whether this is one of the three "commands that matter" shown when argv
    /// is flags-only with no subcommand (bare `jet` starts the REPL instead).
    pub headline: bool,
    /// Nested actions when this is a namespaced group (`registry`, …); empty
    /// for a bare leaf command.
    pub actions: &'static [NestedCommandSpec],
    /// Only meaningful when `actions` is non-empty: true when every subword of
    /// this group is modeled by `actions` — the bare group form and `<group>
    /// help` print the CLI-owned summary, and an unmodeled subword is E2101.
    /// False for `os`/`gc`/`env` (D-CLI-SURFACE3=B): these front doors expose a
    /// wider downstream verb surface
    /// surface (`check`/`build`/`switch`/…) that stays opaque to this
    /// registry, so only the migrated verbs (`push`/`bridge`/`services`/
    /// `config`) are modeled and everything else — including bare `jet os` and
    /// `jet os help` — falls through to the real `jet os` dispatcher unchanged.
    pub exhaustive: bool,
    /// Positional argument shape for a flat command, e.g. `repl [<file.jet>]`
    /// — the same role `NestedCommandSpec::usage` plays for a nested action,
    /// so `command_usage` has one field to read instead of a second table
    /// (#2072). `None` keeps the generic `[args]` shape. Flags are NOT
    /// repeated here: `flags_for_command` already renders them from `FLAGS`.
    pub usage: Option<&'static str>,
}

impl CommandSpec {
    /// True when this row is a namespaced group with nested actions, rather
    /// than a bare leaf command.
    pub const fn is_group(&self) -> bool {
        !self.actions.is_empty()
    }
}

/// One canonical nested spelling and the real legacy dispatcher seam it reaches.
/// `HandlerKey::SharedStore` keeps the group because that handler consumes the
/// group word itself (`shared-store status`, …).
pub struct NestedCommandSpec {
    pub name: &'static str,
    /// Canonical spelling after the group name. Multiple forms use one line each.
    pub usage: &'static str,
    pub summary: &'static str,
    pub handler: HandlerKey,
    /// True when this spelling is also canonical as a top-level command.
    pub also_canonical_top_level: bool,
}
/// The nine canonical views under `jet inspect`.  The enum is the parser's
/// source of truth; the help, completion, and man rows below are generated
/// from the same values.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum InspectPlane {
    Types,
    Rights,
    Claims,
    Shapes,
    Accel,
    Decisions,
    Structure,
    Build,
    Gates,
}

impl InspectPlane {
    pub const ALL: [Self; 9] = [
        Self::Types,
        Self::Rights,
        Self::Claims,
        Self::Shapes,
        Self::Accel,
        Self::Decisions,
        Self::Structure,
        Self::Build,
        Self::Gates,
    ];

    pub const fn name(self) -> &'static str {
        match self {
            Self::Types => "types",
            Self::Rights => "rights",
            Self::Claims => "claims",
            Self::Shapes => "shapes",
            Self::Accel => "accel",
            Self::Decisions => "decisions",
            Self::Structure => "structure",
            Self::Build => "build",
            Self::Gates => "gates",
        }
    }

    pub const fn usage(self) -> &'static str {
        match self {
            Self::Types => "types [TARGET] [--live PID | --replay ARTIFACT]",
            Self::Rights => "rights [TARGET] [--live PID | --replay ARTIFACT]",
            Self::Claims => "claims [TARGET] [--live PID | --replay ARTIFACT]",
            Self::Shapes => "shapes [TARGET] [--live PID | --replay ARTIFACT]",
            Self::Accel => "accel [TARGET] [--live PID | --replay ARTIFACT]",
            Self::Decisions => "decisions [TARGET] [--live PID | --replay ARTIFACT]",
            Self::Structure => "structure [TARGET] [--core] [--live PID | --replay ARTIFACT]",
            Self::Build => "build [TARGET] [--coverage] [--live PID | --replay ARTIFACT]",
            Self::Gates => "gates [TARGET] [--live PID | --replay ARTIFACT]",
        }
    }

    pub const fn summary(self) -> &'static str {
        match self {
            Self::Types => "Show registered type and operator facts",
            Self::Rights => "Show required and granted rights",
            Self::Claims => "Show receipt-backed claims",
            Self::Shapes => "Show semantic shapes and projections",
            Self::Accel => "Show vector proof and acceleration gate decisions",
            Self::Decisions => "Show compiler decisions and their evidence",
            Self::Structure => "Show structure and lifecycle facts",
            Self::Build => "Show build identity, provenance, and coverage",
            Self::Gates => "Show the complete compile-time gate ledger",
        }
    }
}
impl InspectPlane {
    fn parse(name: &str) -> Option<Self> {
        Self::ALL.into_iter().find(|plane| plane.name() == name)
    }
}
pub fn inspect_plane(name: &str) -> Option<InspectPlane> {
    InspectPlane::parse(name)
}

/// Scope selected by the one inspect grammar.  `Target` accepts either a
/// source file or a package directory; the resolver decides which one it is.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum InspectScope {
    Package,
    Target(String),
    Live(u32),
    Replay(String),
}

/// Fully parsed `jet inspect <plane>` request.  `options` retains registered
/// plane flags for the projection backend without making the parser duplicate
/// each plane's option vocabulary.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct InspectRequest {
    pub plane: InspectPlane,
    pub scope: InspectScope,
    pub options: Vec<String>,
}

/// Parse the canonical inspect grammar from the unnormalized argv.
///
/// Plane names come from `INSPECT_ACTIONS`; scope selection is exclusive and
/// deterministic.  Other registered flags stay in `options` for the selected
/// projection and are validated by the shared CLI flag checker.
pub fn parse_inspect_args(args: &[String]) -> Result<InspectRequest, String> {
    if args.first().map(String::as_str) != Some("inspect") {
        return Err("inspect parser expects `jet inspect <plane>`".to_string());
    }
    let plane_name = args.get(1).map(String::as_str).ok_or_else(|| {
        "missing inspect plane; choose types, rights, claims, shapes, accel, decisions, structure, build, or gates"
            .to_string()
    })?;
    let plane = InspectPlane::parse(plane_name).ok_or_else(|| {
        format!(
            "unknown inspect plane `{plane_name}`; choose types, rights, claims, shapes, accel, decisions, structure, build, or gates"
        )
    })?;

    let mut target = None;
    let mut live = None;
    let mut replay = None;
    let mut options = Vec::new();
    let mut index = 2;
    while index < args.len() {
        let argument = args[index].as_str();
        if argument == "--live" {
            let value = args.get(index + 1).map(String::as_str).ok_or_else(|| {
                "`--live` needs a process id".to_string()
            })?;
            live = Some(parse_inspect_pid(value)?);
            options.push("--live".to_string());
            options.push(value.to_string());
            index += 2;
            continue;
        }
        if let Some(value) = argument.strip_prefix("--live=") {
            live = Some(parse_inspect_pid(value)?);
            options.push(argument.to_string());
            index += 1;
            continue;
        }
        if argument == "--replay" {
            let value = args.get(index + 1).map(String::as_str).ok_or_else(|| {
                "`--replay` needs a replay artifact path".to_string()
            })?;
            if value.starts_with('-') {
                return Err("`--replay` needs a replay artifact path".to_string());
            }
            replay = Some(value.to_string());
            options.push("--replay".to_string());
            options.push(value.to_string());
            index += 2;
            continue;
        }
        if let Some(value) = argument.strip_prefix("--replay=") {
            if value.is_empty() {
                return Err("`--replay` needs a replay artifact path".to_string());
            }
            replay = Some(value.to_string());
            options.push(argument.to_string());
            index += 1;
            continue;
        }
        if argument == "--" {
            return Err("inspect planes do not accept a `--` command tail".to_string());
        }
        if argument.starts_with('-') {
            options.push(argument.to_string());
            if inspect_flag_takes_value(argument) {
                if let Some(value) = args.get(index + 1) {
                    if !value.starts_with('-') {
                        options.push(value.clone());
                        index += 2;
                        continue;
                    }
                }
            }
            index += 1;
            continue;
        }
        if target.replace(argument.to_string()).is_some() {
            return Err("inspect accepts at most one file or package target".to_string());
        }
        index += 1;
    }

    if live.is_some() && replay.is_some() {
        return Err("inspect accepts at most one of `--live PID` or `--replay ARTIFACT`".to_string());
    }
    if target.is_some() && (live.is_some() || replay.is_some()) {
        return Err("inspect accepts a target, `--live PID`, or `--replay ARTIFACT` as one scope".to_string());
    }
    let scope = match (target, live, replay) {
        (Some(target), None, None) => InspectScope::Target(target),
        (None, Some(pid), None) => InspectScope::Live(pid),
        (None, None, Some(artifact)) => InspectScope::Replay(artifact),
        (None, None, None) => InspectScope::Package,
        _ => unreachable!("inspect scope exclusivity is checked above"),
    };
    Ok(InspectRequest {
        plane,
        scope,
        options,
    })
}

fn parse_inspect_pid(value: &str) -> Result<u32, String> {
    let pid = value
        .parse::<u32>()
        .map_err(|_| format!("`--live` expects a positive process id, got `{value}`"))?;
    if pid == 0 {
        return Err("`--live` expects a positive process id".to_string());
    }
    Ok(pid)
}

fn inspect_flag_takes_value(argument: &str) -> bool {
    let name = argument.split('=').next().unwrap_or(argument);
    matches!(
        name,
        "--before"
            | "--color"
            | "--facts"
            | "--gate"
            | "--kind"
            | "--output"
            | "--profile"
            | "--scope"
            | "--set"
            | "--target"
            | "--topic"
    )
}

const fn inspect_plane_action(plane: InspectPlane) -> NestedCommandSpec {
    NestedCommandSpec {
        name: plane.name(),
        usage: plane.usage(),
        summary: plane.summary(),
        handler: HandlerKey::InspectPlane,
        also_canonical_top_level: false,
    }
}


/// Closed set of real dispatcher seams reachable from nested commands.
/// Adding a handler requires updating this exhaustive mapping and its route test.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum HandlerKey {
    Publish,
    Yank,
    Keygen,
    Key,
    Vendor,
    Graph,
    Query,
    ExplainBuild,
    Compiler,
    Impact,
    Provenance,
    Digest,
    InspectPlane,
    Schema,
    Semindex,
    Output,
    Expand,
    Codemod,
    Audit,
    Sbom,
    Bind,
    Logs,
    Info,
    Outdated,
    GcReport,
    ProjectParts,
    Push,
    Bridge,
    Services,
    Config,
    Toolchain,
    SelfUpdate,
    Doctor,
    Completions,
    Man,
    Devtools,
    Lsp,
    Exec,
    Env,
    SharedStore,
    Cache,
    Perf,
    Reserved,
    Db,
}

impl HandlerKey {
    pub const fn dispatch_word(self) -> &'static str {
        match self {
            Self::Publish => "publish",
            Self::Yank => "yank",
            Self::Keygen => "keygen",
            Self::Key => "key",
            Self::Vendor => "vendor",
            Self::Graph => "graph",
            Self::Query => "query",
            Self::ExplainBuild => "explain-build",
            Self::Compiler => "compiler",
            Self::Impact => "impact",
            Self::Provenance => "provenance",
            Self::Digest => "digest",
            Self::Env => "env",
            Self::Semindex => "semindex",
            Self::Output => "output",
            Self::Expand => "expand",
            Self::InspectPlane => "inspect",
            Self::Schema => "schema",
            Self::Codemod => "codemod",
            Self::Audit => "audit",
            Self::Sbom => "sbom",
            Self::Bind => "bind",
            Self::Logs => "logs",
            Self::Info => "info",
            Self::Outdated => "outdated",
            Self::GcReport => "gc",
            Self::ProjectParts => "parts",
            Self::Push => "push",
            Self::Bridge => "bridge",
            Self::Services => "services",
            Self::Config => "config",
            Self::Toolchain => "toolchain",
            Self::SelfUpdate => "self-update",
            Self::Doctor => "doctor",
            Self::Completions => "completions",
            Self::Man => "man",
            Self::Devtools => "devtools",
            Self::Lsp => "lsp",
            Self::Exec => "exec",
            Self::SharedStore => "shared-store",
            Self::Cache => "cache",
            Self::Perf => "perf",
            Self::Reserved => "reserved",
            Self::Db => "db",
        }
    }

    pub const fn keeps_group(self) -> bool {
        matches!(
            self,
            Self::InspectPlane
                | Self::GcReport
                | Self::Perf
                | Self::Env
                | Self::SharedStore
                | Self::Cache
                | Self::Db
        )
    }
}

