/// Is `flag` (e.g. `--json` or `--color=always`) a known flag?
pub fn is_known_flag(flag: &str) -> bool {
    let head = flag.split('=').next().unwrap_or(flag);
    FLAGS.iter().any(|f| f.long == head)
}

/// #1659 criterion 2: the one spelling-check for "the user asked for help",
/// shared by every command instead of each hand-copying
/// `arg == "--help" || arg == "-h"`.
pub fn is_help_flag(arg: &str) -> bool {
    arg == "--help" || arg == "-h"
}

/// Levenshtein edit distance — the same shape used by sema's S14 suggestions.
/// Closest built-in command to `name` within edit distance 3, or `None`.
pub fn closest_command(name: &str) -> Option<&'static str> {
    closest(
        name,
        COMMANDS
            .iter()
            .filter(|command| is_canonical_top_level(command.name))
            .map(|command| command.name),
    )
}

/// Closest known flag to `flag` within edit distance 3, or `None`.
pub fn closest_flag(flag: &str) -> Option<&'static str> {
    let head = flag.split('=').next().unwrap_or(flag);
    closest(head, FLAGS.iter().map(|f| f.long))
}

fn closest<'a, I: Iterator<Item = &'a str>>(needle: &str, hay: I) -> Option<&'a str> {
    let mut best: Option<(&str, usize)> = None;
    for cand in hay {
        let d = edit_distance(needle, cand);
        if best.map(|(_, bd)| d < bd).unwrap_or(true) {
            best = Some((cand, d));
        }
    }
    // Cap: only suggest when reasonably close (allow ~half the word length).
    best.filter(|(c, d)| *d <= 3 && *d <= c.len())
        .map(|(c, _)| c)
}

