// Generators (hand-rolled — invariant I6, no clap_complete)
// ──────────────────────────────────────────────

/// bash completion script for `jet`.
pub fn completions_bash() -> String {
    let cmds = COMMANDS
        .iter()
        .filter(|c| is_canonical_top_level(c.name))
        .map(|c| c.name)
        .collect::<Vec<_>>()
        .join(" ");
    let flags = FLAGS.iter().map(|f| f.long).collect::<Vec<_>>().join(" ");
    let job_completion = format!(
        "    if [[ $COMP_CWORD -eq 2 && \"${{COMP_WORDS[1]}}\" == \"jobs\" ]]; then\n\
        local job_names\n\
        job_names=\"$({bin} --json jobs 2>/dev/null | sed -n 's/.*\"name\":\"\\([^\"]*\\)\".*/\\1/p')\"\n\
        COMPREPLY=( $(compgen -W \"$job_names\" -- \"$cur\") )\n\
        return 0\n\
    fi\n",
        bin = BINARY_NAME,
    );
    let nested = command_groups()
        .map(|g| {
            format!(
                "        {}) COMPREPLY=( $(compgen -W \"{}\" -- \"$cur\") ); return 0 ;;",
                g.name,
                g.actions
                    .iter()
                    .map(|a| a.name)
                    .collect::<Vec<_>>()
                    .join(" ")
            )
        })
        .collect::<Vec<_>>()
        .join("\n");
    format!(
        "# bash completion for {bin} (generated by `{bin} self completions bash`)\n\
_{bin}() {{\n\
    local cur prev cmds flags\n\
    COMPREPLY=()\n\
    cur=\"${{COMP_WORDS[COMP_CWORD]}}\"\n\
    cmds=\"{cmds}\"\n\
    flags=\"{flags}\"\n\
    if [[ \"$cur\" == -* ]]; then\n\
        COMPREPLY=( $(compgen -W \"$flags\" -- \"$cur\") )\n\
        return 0\n\
    fi\n\
    if [[ $COMP_CWORD -eq 1 ]]; then\n\
        COMPREPLY=( $(compgen -W \"$cmds\" -- \"$cur\") )\n\
        return 0\n\
    fi\n\
{job_completion}    if [[ $COMP_CWORD -eq 2 ]]; then\n\
        case \"${{COMP_WORDS[1]}}\" in\n{nested}\n        esac\n\
    fi\n\
    COMPREPLY=( $(compgen -f -- \"$cur\") )\n\
}}\n\
complete -F _{bin} {bin}\n",
        bin = BINARY_NAME,
        cmds = cmds,
        flags = flags,
        nested = nested,
    )
}

/// zsh completion script for `jet`.
pub fn completions_zsh() -> String {
    let mut cmd_lines = String::new();
    for c in COMMANDS {
        if !is_canonical_top_level(c.name) {
            continue;
        }
        cmd_lines.push_str(&format!("        '{}:{}'\n", c.name, escape_zsh(c.summary)));
    }
    let nested = command_groups()
        .map(|g| {
            format!(
                "            {}) _values 'action' {} ;;",
                g.name,
                g.actions
                    .iter()
                    .map(|a| format!("'{}:{}'", a.name, escape_zsh(a.summary)))
                    .collect::<Vec<_>>()
                    .join(" ")
            )
        })
        .collect::<Vec<_>>()
        .join("\n");
    let mut flag_lines = String::new();
    for f in FLAGS.iter() {
        flag_lines.push_str(&format!("        '{}[{}]'\n", f.long, escape_zsh(f.help)));
    }
    let job_completion = format!(
        "        local -a job_names\n\
        job_names=(\"${{(@f)$({bin} --json jobs 2>/dev/null | sed -n 's/.*\"name\":\"\\([^\"]*\\)\".*/\\1/p')}}\")\n\
        _describe -t job_names 'job' job_names\n",
        bin = BINARY_NAME,
    );
    format!(
        "#compdef {bin}\n\
# zsh completion for {bin} (generated by `{bin} self completions zsh`)\n\
_{bin}() {{\n\
    local -a commands flags\n\
    commands=(\n{cmds}    )\n\
    flags=(\n{flags}    )\n\
    if (( CURRENT == 2 )); then\n\
        _describe -t commands 'command' commands\n\
    elif (( CURRENT == 3 && $words[2] == jobs )); then\n\
{job_completion}    else\n\
        if (( CURRENT == 3 )); then\n\
            case $words[2] in\n{nested}\n            esac\n\
        else\n\
            _values 'flag' $flags\n\
            _files\n\
        fi\n\
    fi\n\
}}\n\
_{bin} \"$@\"\n",
        bin = BINARY_NAME,
        cmds = cmd_lines,
        flags = flag_lines,
        nested = nested,
    )
}

/// fish completion script for `jet`.
pub fn completions_fish() -> String {
    let mut out = format!(
        "# fish completion for {bin} (generated by `{bin} self completions fish`)\n",
        bin = BINARY_NAME
    );
    // Only complete subcommands when none has been seen yet.
    let seen = "__fish_use_subcommand";
    for c in COMMANDS {
        if !is_canonical_top_level(c.name) {
            continue;
        }
        out.push_str(&format!(
            "complete -c {bin} -n '{seen}' -a {name} -d '{desc}'\n",
            bin = BINARY_NAME,
            seen = seen,
            name = c.name,
            desc = escape_fish(c.summary),
        ));
    }
    for group in command_groups() {
        for action in group.actions {
            out.push_str(&format!("complete -c {bin} -n '__fish_seen_subcommand_from {group}' -a {action} -d '{desc}'\n", bin=BINARY_NAME, group=group.name, action=action.name, desc=escape_fish(action.summary)));
        }
    }
    for f in FLAGS.iter() {
        out.push_str(&format!(
            "complete -c {bin} -l {long} -d '{desc}'\n",
            bin = BINARY_NAME,
            long = f.long.trim_start_matches("--"),
            desc = escape_fish(f.help),
        ));
    }
    out.push_str(&format!(
        "complete -c {bin} -n '__fish_seen_subcommand_from jobs' -a \"({bin} --json jobs 2>/dev/null | string match -r '\\\"name\\\":\\\"[^\\\"]+\\\"' | string replace -r '.*\\\"name\\\":\\\"([^\\\"]+)\\\".*' '$1')\" -d 'job name'\n",
        bin = BINARY_NAME,
    ));
    out
}

/// PowerShell completion script, derived from the same nested registry.
pub fn completions_powershell() -> String {
    let top = COMMANDS
        .iter()
        .filter(|c| is_canonical_top_level(c.name))
        .map(|c| format!("'{}'", c.name))
        .collect::<Vec<_>>()
        .join(",");
    let groups = command_groups()
        .map(|g| {
            format!(
                "'{}' = @({})",
                g.name,
                g.actions
                    .iter()
                    .map(|a| format!("'{}'", a.name))
                    .collect::<Vec<_>>()
                    .join(",")
            )
        })
        .collect::<Vec<_>>()
        .join("; ");
    let flags = FLAGS
        .iter()
        .map(|f| format!("'{}'", f.long))
        .collect::<Vec<_>>()
        .join(",");
    let job_completion = format!(
        "$JetJobs = @((& {bin} --json jobs 2>$null | ConvertFrom-Json).jobs.name)\n",
        bin = BINARY_NAME,
    );
    format!(
        "# PowerShell completion for {bin} (generated by `{bin} self completions powershell`)\n\
$JetCommands = @({top})\n\
$JetFlags = @({flags})\n\
$JetGroups = @{{ {groups} }}\n\
{job_completion}\
Register-ArgumentCompleter -Native -CommandName {bin} -ScriptBlock {{\n\
    param($wordToComplete,$commandAst,$cursorPosition)\n\
    $words = @($commandAst.CommandElements | ForEach-Object {{ $_.Extent.Text }})\n\
    $choices = if ($wordToComplete.StartsWith('-')) {{\n\
        $JetFlags\n\
    }} elseif ($words.Count -ge 2 -and $words[1] -eq 'jobs') {{\n\
        $JetJobs\n\
    }} elseif ($words.Count -ge 2 -and $JetGroups.ContainsKey($words[1])) {{\n\
        $JetGroups[$words[1]]\n\
    }} else {{\n\
        $JetCommands\n\
    }}\n\
    $choices | Where-Object {{ $_ -like \"$wordToComplete*\" }} |\n\
        ForEach-Object {{ [System.Management.Automation.CompletionResult]::new($_,$_,\"ParameterValue\",$_) }}\n\
}}\n",
        bin = BINARY_NAME,
        top = top,
        flags = flags,
        groups = groups,
        job_completion = job_completion,
    )
}

/// D-SHAPE-CLI-COMPLETE1=A: render a completion script for a compiled Jet
/// program from its verified embedded schema. Only schema-known flags are
/// candidates; application code is never executed and live values are never
/// queried.
pub fn completions_for_program(
    shell: &str,
    command_name: &str,
    schema: &jet_foundation::CLISchema::CLICommandSchema,
) -> Option<String> {
    debug_assert!(!command_name.chars().any(char::is_control));
    let root_words = schema.completion_words();
    let root_input_words = schema.root_completion_words();
    match shell {
        "bash" => {
            if schema.commands.is_empty() {
                return Some(format!(
                    "# bash completion from JetCommandSchema v{}\n__jet_program_completion() {{\n    local cur\n    COMPREPLY=()\n    cur=\"${{COMP_WORDS[COMP_CWORD]}}\"\n    COMPREPLY=( $(compgen -W {} -- \"$cur\") )\n}}\ncomplete -F __jet_program_completion -- {}\n",
                    jet_foundation::CLISchema::RECORD_VERSION,
                    shell_single_quote(&root_words.join(" ")),
                    shell_single_quote(command_name),
                ));
            }
            let cases = schema
                .commands
                .iter()
                .map(|command| {
                    format!(
                        "        {}) flags={} ;;",
                        shell_single_quote(&command.name),
                        shell_single_quote(&schema.command_completion_words(command).join(" ")),
                    )
                })
                .collect::<Vec<_>>()
                .join("\n");
            Some(format!(
                "# bash completion from JetCommandSchema v{}\n__jet_program_completion() {{\n    local cur flags\n    COMPREPLY=()\n    cur=\"${{COMP_WORDS[COMP_CWORD]}}\"\n    if [[ $COMP_CWORD -eq 1 ]]; then\n        COMPREPLY=( $(compgen -W {} -- \"$cur\") )\n        return 0\n    fi\n    flags={}\n    case \"${{COMP_WORDS[1]}}\" in\n{}\n    esac\n    if [[ \"$cur\" == -* ]]; then\n        COMPREPLY=( $(compgen -W \"$flags\" -- \"$cur\") )\n    fi\n}}\ncomplete -F __jet_program_completion -- {}\n",
                jet_foundation::CLISchema::RECORD_VERSION,
                shell_single_quote(&root_words.join(" ")),
                shell_single_quote(&root_input_words.join(" ")),
                cases,
                shell_single_quote(command_name),
            ))
        }
        "zsh" => {
            if schema.commands.is_empty() {
                let mut specs = zsh_standard_specs(schema.standard, schema.version.is_some());
                specs.extend(zsh_input_specs(&schema.inputs));
                let args = specs.join(" \\\n");
                return Some(format!(
                    "#compdef {}\n# zsh completion from JetCommandSchema v{}\n_arguments \\\n{}\n",
                    shell_single_quote(command_name),
                    jet_foundation::CLISchema::RECORD_VERSION,
                    args,
                ));
            }
            // The whole `_arguments` spec is already single-quoted below.
            // Jet command words are checked identifiers; quoting each word
            // again produces literal quote characters in zsh's candidate list.
            let commands = schema
                .commands
                .iter()
                .map(|command| command.name.as_str())
                .collect::<Vec<_>>()
                .join(" ");
            let mut root_specs = zsh_standard_specs(schema.standard, schema.version.is_some());
            root_specs.extend(zsh_input_specs(&schema.inputs));
            root_specs.push(format!("    '1:command:({commands})'"));
            let root_args = root_specs.join(" \\\n");
            let cases = schema
                .commands
                .iter()
                .map(|command| {
                    format!(
                        "        {}) _arguments \\\n{} ;;",
                        shell_single_quote(&command.name),
                        {
                            let specs = zsh_input_specs(&schema.command_inputs(command));
                            specs.join(" \\\n")
                        },
                    )
                })
                .collect::<Vec<_>>()
                .join("\n");
            Some(format!(
                "#compdef {}\n# zsh completion from JetCommandSchema v{}\nif (( CURRENT == 2 )); then\n_arguments \\\n{}\nelse\n    case $words[2] in\n{}\n    esac\nfi\n",
                shell_single_quote(command_name), jet_foundation::CLISchema::RECORD_VERSION, root_args, cases,
            ))
        }
        "fish" => {
            let mut out = format!(
                "# fish completion from JetCommandSchema v{}\n",
                jet_foundation::CLISchema::RECORD_VERSION
            );
            let root_condition = if schema.commands.is_empty() {
                ""
            } else {
                " -n '__fish_use_subcommand'"
            };
            out.push_str(&format!(
                "complete -c {}{} -l help -d 'show help'\n",
                fish_single(command_name),
                root_condition
            ));
            if schema.standard {
                out.push_str(&format!(
                    "complete -c {}{} -l verbose -s v -d 'print extra detail'\n",
                    fish_single(command_name),
                    root_condition
                ));
                out.push_str(&format!(
                    "complete -c {}{} -l quiet -s q -d 'suppress normal output'\n",
                    fish_single(command_name),
                    root_condition
                ));
                out.push_str(&format!(
                    "complete -c {}{} -l color -r -d 'control terminal color'\n",
                    fish_single(command_name),
                    root_condition
                ));
                if schema.version.is_some() {
                    out.push_str(&format!(
                        "complete -c {}{} -l version -d 'show version'\n",
                        fish_single(command_name),
                        root_condition
                    ));
                }
            }
            for input in &schema.inputs {
                let short = input
                    .short
                    .as_ref()
                    .map_or_else(String::new, |short| format!(" -s {short}"));
                out.push_str(&format!(
                    "complete -c {}{} -l {}{} -d {}{}\n",
                    fish_single(command_name),
                    root_condition,
                    input.flag,
                    short,
                    fish_single(&input.help),
                    if input.metavar.is_some() { " -r" } else { "" }
                ));
            }
            for command in &schema.commands {
                out.push_str(&format!(
                    "complete -c {} -n '__fish_use_subcommand' -a {}\n",
                    fish_single(command_name),
                    fish_single(&command.name)
                ));
                out.push_str(&format!(
                    "complete -c {} -n '__fish_seen_subcommand_from {}' -l help -d 'show help'\n",
                    fish_single(command_name),
                    command.name
                ));
                let command_inputs = schema.command_inputs(command);
                for input in &command_inputs {
                    let short = input
                        .short
                        .as_ref()
                        .map_or_else(String::new, |short| format!(" -s {short}"));
                    out.push_str(&format!(
                        "complete -c {} -n '__fish_seen_subcommand_from {}' -l {}{} -d {}{}\n",
                        fish_single(command_name),
                        command.name,
                        input.flag,
                        short,
                        fish_single(&input.help),
                        if input.metavar.is_some() { " -r" } else { "" }
                    ));
                }
            }
            Some(out)
        }
        "powershell" => {
            let root = root_words
                .iter()
                .map(|word| ps_single(word))
                .collect::<Vec<_>>()
                .join(",");
            if schema.commands.is_empty() {
                return Some(format!("# PowerShell completion from JetCommandSchema v{}\nRegister-ArgumentCompleter -Native -CommandName {} -ScriptBlock {{ param($wordToComplete,$commandAst,$cursorPosition) @({root}) | Where-Object {{ $_ -like \"$wordToComplete*\" }} | ForEach-Object {{ [System.Management.Automation.CompletionResult]::new($_,$_,'ParameterName',$_) }} }}\n", jet_foundation::CLISchema::RECORD_VERSION, ps_single(command_name)));
            }
            let flags = root_input_words
                .iter()
                .map(|word| ps_single(word))
                .collect::<Vec<_>>()
                .join(",");
            let command_flags = schema
                .commands
                .iter()
                .map(|command| {
                    format!(
                        "{} = @({})",
                        ps_single(&command.name),
                        schema
                            .command_completion_words(command)
                            .iter()
                            .map(|word| ps_single(word))
                            .collect::<Vec<_>>()
                            .join(","),
                    )
                })
                .collect::<Vec<_>>()
                .join("; ");
            Some(format!("# PowerShell completion from JetCommandSchema v{}\nRegister-ArgumentCompleter -Native -CommandName {} -ScriptBlock {{ param($wordToComplete,$commandAst,$cursorPosition) $root = @({root}); $flags = @({flags}); $commandFlags = @{{ {command_flags} }}; $words = @($commandAst.CommandElements | ForEach-Object {{ $_.Extent.Text }}); $selected = if ($words.Count -ge 2) {{ $words[1] }} else {{ '' }}; $choices = if ($commandFlags.ContainsKey($selected)) {{ $commandFlags[$selected] }} elseif ($wordToComplete.StartsWith('-')) {{ $flags }} else {{ $root }}; $choices | Where-Object {{ $_ -like \"$wordToComplete*\" }} | ForEach-Object {{ [System.Management.Automation.CompletionResult]::new($_,$_,'ParameterName',$_) }} }}\n", jet_foundation::CLISchema::RECORD_VERSION, ps_single(command_name)))
        }
        _ => None,
    }
}

/// Registration uses executable basename, never a path/comment payload.
pub fn completion_command_name(program: &str) -> Result<String, &'static str> {
    let name = std::path::Path::new(program)
        .file_name()
        .and_then(|name| name.to_str())
        .filter(|name| !name.is_empty())
        .ok_or("the program path has no usable command name")?;
    if name.chars().any(char::is_control) {
        return Err("the program command name contains a control character");
    }
    Ok(name.to_string())
}

fn zsh_standard_specs(standard: bool, version: bool) -> Vec<String> {
    if !standard {
        return Vec::new();
    }
    let mut specs = vec![
        "    '(-v --verbose){-v,--verbose}[print extra detail]'".to_string(),
        "    '(-q --quiet){-q,--quiet}[suppress normal output]'".to_string(),
        "    '--color[control terminal color]:MODE:(auto always never)'".to_string(),
    ];
    if version {
        specs.push("    '--version[show version]'".to_string());
    }
    specs
}

fn zsh_input_specs(inputs: &[jet_foundation::CLISchema::CLIInputSchema]) -> Vec<String> {
    let mut specs = Vec::new();
    let mut positionals: Vec<&jet_foundation::CLISchema::CLIInputSchema> = inputs
        .iter()
        .filter(|input| input.positional.is_some())
        .collect();
    positionals.sort_by_key(|input| input.positional.unwrap());
    for input in positionals {
        let meta = input
            .metavar
            .as_deref()
            .unwrap_or(input.flag.as_str())
            .to_lowercase();
        specs.push(format!(
            "    ':{}:{}'",
            zsh_single(&meta),
            zsh_bracket(&input.help)
        ));
    }
    specs.extend(inputs.iter().map(|input| {
        let value = input
            .metavar
            .as_deref()
            .map(|name| format!(":{}:", name.to_lowercase()))
            .unwrap_or_default();
        let names = input.short.as_ref().map_or_else(
            || format!("--{}", input.flag),
            |short| format!("(-{short} --{}){{-{short},--{}}}", input.flag, input.flag),
        );
        format!(
            "    '{}[{}]{}'",
            zsh_single(&names),
            zsh_bracket(&input.help),
            value
        )
    }));
    specs.push("    '--help[show help]'".to_string());
    specs
}

fn shell_single_quote(value: &str) -> String {
    format!("'{}'", value.replace('\'', "'\\''"))
}
fn zsh_single(value: &str) -> String {
    value.replace('\'', "'\\''")
}
fn zsh_bracket(value: &str) -> String {
    zsh_single(value).replace('[', "\\[").replace(']', "\\]")
}
fn fish_single(value: &str) -> String {
    shell_single_quote(value)
}
fn ps_single(value: &str) -> String {
    format!("'{}'", value.replace('\'', "''"))
}

/// roff man page for `jet`, section 1.
pub fn man_page(version: &str) -> String {
    let mut out = String::new();
    out.push_str(&format!(
        ".TH {bin_up} 1 \"\" \"{bin} {ver}\" \"Jet Manual\"\n",
        bin_up = BINARY_NAME.to_uppercase(),
        bin = BINARY_NAME,
        ver = version,
    ));
    out.push_str(".SH Name\n");
    out.push_str(&format!(
        "{bin} \\- the Jet compiler and project tool\n",
        bin = BINARY_NAME
    ));
    out.push_str(".SH Synopsis\n");
    out.push_str(&format!(
        ".B {bin}\n.RI [ command ] \" \" [ args ...]\n",
        bin = BINARY_NAME
    ));
    out.push_str(".SH Description\n");
    out.push_str(&format!(
        "{bin} builds, checks, runs, and tests Jet programs, and manages Jet projects \
and their dependencies. Output is plain when piped and colored on a terminal.\n",
        bin = BINARY_NAME
    ));
    out.push_str(".SH Commands\n");
    for c in COMMANDS {
        if !is_canonical_top_level(c.name) {
            continue;
        }
        out.push_str(&format!(".TP\n.B {}\n{}\n", c.name, roff_escape(c.summary)));
        if let Some(group) = command_group(c.name) {
            for action in group.actions {
                out.push_str(&format!(
                    ".TP\n.B {} {}\n{}\n",
                    group.name,
                    action.name,
                    roff_escape(action.summary)
                ));
            }
        }
    }
    out.push_str(".SH Flags\n");
    for f in FLAGS.iter() {
        out.push_str(&format!(".TP\n.B {}\n{}\n", f.long, roff_escape(f.help)));
    }
    out.push_str(".SH Files\n");
    out.push_str(&format!(
        ".TP\n.B {manifest}\nThe project manifest.\n",
        manifest = crate::Syntax::PAYLOAD_FILE
    ));
    out.push_str(".SH See Also\n");
    out.push_str(&format!("{bin}-explain(1)\n", bin = BINARY_NAME));
    out
}

fn escape_zsh(s: &str) -> String {
    s.replace('\'', "'\\''")
        .replace(':', "\\:")
        .replace('[', "\\[")
        .replace(']', "\\]")
}
fn escape_fish(s: &str) -> String {
    s.replace('\'', "\\'")
}
fn roff_escape(s: &str) -> String {
    // Lines beginning with `'` or `.` are roff control lines; escape and also
    // neutralize backslashes.
    s.replace('\\', "\\\\")
}

